import { test, expect } from '@playwright/test';

test.describe('User mention in comments', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
    await page.fill('input[name="username"]', 'testuser'); // Replace with actual selector
    await page.fill('input[name="password"]', 'password'); // Replace with actual selector
    await page.click('button[type="submit"]'); // Replace with actual selector
    await expect(page).toHaveURL('https://example.com/dashboard'); // Replace with actual URL
  });

  test('should mention another user in a comment', async ({ page }) => {
    await page.click(getByRole('button', { name: /add comment/i }));
    await page.fill(getByLabel('Comment'), 'Hello @anotheruser!'); // Replace with actual label
    await page.click(getByRole('button', { name: /submit/i }));

    const comment = await page.locator(getByText('Hello @anotheruser!'));
    await expect(comment).toBeVisible();
  });

  test('should display mentioned user in comment', async ({ page }) => {
    await page.click(getByRole('button', { name: /view comments/i }));
    const mentionedUser = await page.locator(getByText('@anotheruser'));
    await expect(mentionedUser).toBeVisible();
  });
});
